import numpy as np, math
lines = open("xtbopt.xyz").read().splitlines()
n = int(lines[0]); els=[]; xyz=[]
for l in lines[2:2+n]:
    p=l.split(); els.append(p[0]); xyz.append([float(v) for v in p[1:4]])
xyz=np.array(xyz)
def d(i,j): return np.linalg.norm(xyz[i]-xyz[j])
def ang(i,j,k):
    v1=xyz[i]-xyz[j]; v2=xyz[k]-xyz[j]
    return math.degrees(math.acos(v1.dot(v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
pd=42
print("Pd-P8 %.2f Pd-P29 %.2f Pd-C43 %.2f Pd-C44 %.2f"%(d(pd,8),d(pd,29),d(pd,43),d(pd,44)))
print("P-Pd-P %.1f  C43-Pd-C44 %.1f"%(ang(8,pd,29),ang(43,pd,44)))
print("C43-C44 %.2f"%(d(43,44)))
# ring planarity / other ring distances
for i in range(43,49):
    for j in range(i+1,49):
        if d(i,j)<1.6: print("ring bond",i,j,round(d(i,j),2))
# closest H to Pd
hs=[i for i,e in enumerate(els) if e=="H"]
print("min Pd-H:", round(min(d(pd,i) for i in hs),2))
